function getNestedObject(obj, path) {
    // Split the path into individual keys
    const [keyPath] = path.split('.');

    // Split each key in the path on '.' and then join them back together as array of strings
    const keys = keyPath.split('.').map(key => key.trim());

    // Create a map from the current object's properties to their values
    let result = new Map();

    for (const prop in obj) {
        if (obj.hasOwnProperty(prop)) {
            // If we find a property whose name matches any part of our path,
            // add it to the results.
            const parts = prop.split('.');
            const matchingParts = parts.filter(part => keys.includes(part));

            if (matchingParts.length === keys.length) {
                result.set(parts[0], obj[prop]);
            }
        }
    }

    // Return the resulting map converted to an object
    return Object.fromEntries(result);
}

